        elif new[k - 1] == 'E':
            new = new[:k - 1] + new[k:]
        k += 1        # extra to cover skipped spots due to length change in str
    return(new)

def do_filesizeformat(value, binary=False):
    bytes = float(value)
    base = binary and 1024 or 1000
    prefixes = [
        (binary and "KiB" or "kB"),
        (binary and "MiB" or "MB"),
        (binary and "GiB" or "GB"),
        (binary and "TiB" or "TB"),
        (binary and "PiB" or "PB"),
        (binary and "EiB" or "EB"),
        (binary and "ZiB" or "ZB"),
        (binary and "YiB" or "YB")
    ]
    if bytes == 1:
        return "1 Byte"
    elif bytes < base:
        return "%d Bytes" % bytes
    else:
        for i, prefix in enumerate(prefixes):
            unit = base * base ** (i + 1)
            if bytes < unit:
                return "%.1f %s" % ((bytes / unit), prefix)
        return "%.1f %s" % ((bytes / unit), prefix)

def is_degree_in_degree_range(degree_a, degree_b, degree_c):
    degrees_omni = [degree_a, degree_b, degree_c]

    for x in range(len(degrees_omni)):
        if degrees_omni[x] > 180 or degrees_omni[x] <= -180:
            degrees_omni[x] = -180 * (((degrees_omni[x] // 180) % 2) * degrees_omni[x]/abs(degrees_omni[x])) + (degrees_omni[x] % 180)

    degree_a = degrees_omni[0]
    degree_b = degrees_omni[1]
    degree_c = degrees_omni[2]

    clockwise = degree_a
    counterclock = degree_b

    if clockwise > counterclock:
        if degree_c <= clockwise and degree_c >= counterclock:
            return True
    elif clockwise < counterclock and clockwise <= 0 and counterclock > 0:
        if degree_c >= counterclock or degree_c <= clockwise:
            return True
    return False

def is_valid_value(bo, num, pos):
    # Check column for same number
    for rows in range(len(bo)):
        if bo[rows][pos[1]] == num and pos[0] != rows:
            return False

    # Check row for same number
    for cols in range(len(bo[pos[0]])):
        if bo[pos[0]][cols] == num and pos[1] != cols:
            return False

    # Check box for same number
    box_row = pos[0] // 3    # "//" -> Floor division b/c "/" returns decimal
    box_col = pos[1] // 3

    for rows in range(box_row * 3, box_row * 3 + 3):
        for cols in range(box_col * 3, box_col * 3 + 3):
            if bo[rows][cols] == num and (rows, cols) != pos:
                return False

    # Passed all checks -> number is valid
    return True

def count_alive_neighbors(grid, x, y):
    height = len(grid)
    width = len(grid[0])
    alive_count = 0
    for i in range(-1, 2):
        for j in range(-1, 2):
            neighbor_x = x + i
            neighbor_y = y + j
            if i == 0 and j == 0:
                continue
            elif neighbor_x <= 0 or neighbor_y <= 0 or neighbor_y >= height - 1 or neighbor_x >= width - 1:
                # Edges are considered alive. Makes map more likely to appear naturally closed.
                alive_count += 1
            elif grid[neighbor_y][neighbor_x] == 1:
                alive_count += 1
    return alive_count

def get_adjacent_buckets(cx, cy, buckets):
    c_bucket = []
    b_length = len(buckets[0])

    if cx - 1 >= 0:
        c_bucket  += buckets[cy    ][cx - 1]
    if cx - 1 >= 0 and cy - 1 >= 0:
        c_bucket += buckets[cy - 1][cx - 1]
    if cy - 1 >= 0:
        c_bucket += buckets[cy - 1][cx]
    if cx + 1 < b_length and cy - 1 >= 0:
        c_bucket += buckets[cy - 1][cx + 1]
    if cx + 1 < b_length:
        c_bucket  += buckets[cy    ][cx + 1]
    if cx + 1 < b_length and cy + 1 < b_length:
        c_bucket += buckets[cy + 1][cx + 1]
    if cy + 1 < b_length:
        c_bucket  += buckets[cy + 1][cx    ]
    if cx - 1 >= 0 and cy + 1 < b_length:
        c_bucket += buckets[cy + 1][cx - 1]

    return c_bucket + buckets[cy][cx]

